            accessibility: 100,
            'best-practices': 100,
            performance: 100,
            pwa: 30,
            seo: 91,
          },
        },
      ],
    };

    await lighthousePlugin().onSuccess({ utils: mockUtils });
    const [resultMessage, resultPayload] =
      mockUtils.build.failPlugin.mock.calls[0];

    expect(stripAnsi(resultMessage).split('\n').filter(Boolean)).toEqual(
      message,
    );
    expect(resultPayload).toEqual(payload);

    // This should only be called onPostBuild
    expect(mockUtils.build.failBuild).not.toHaveBeenCalled();
  });
});

